import React from "react";

export default function ManifestSummary({ count, value }) {
  return (
    <div className="flex flex-row w-full font-bold text-3xl justify-around">
      <div>
        <p>TICKETS: {count}</p>
      </div>
      <div>
        <p>TOTAL AMOUNT: KES {value}</p>
      </div>
    </div>
  );
}
