import React, { useRef, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import ReactToPrint from "react-to-print";
import { useStateContext } from "../../../contexts/ContextProvider";
import Header from "./Header";
import MainDetails from "./MainDetails";
import Table from "./Table";
import ManifestSummary from "./ManifestSummary";
import ItemsSummary from "./ItemsSummary";

export default function Manifest(props) {
  const [tickets, settickets] = useState([]);
  const { loggedInUser, currentColor } = useStateContext();
  const componentRef = useRef();
  const location = useLocation();
  //   settickets(location.state.tickets);
  console.log("Use params", location.state);
  console.log("User", loggedInUser);

  const handlePrint = () => {
    window.print();
  };

  const getValue = (data) => {
    console.log("data", data);
    let value = 0.0;
    data.map((x) => {
      value = value + parseFloat(x.ticket_total_amount);
    });

    // settotalValue(value.toFixed(2));
    return value.toFixed(2);
  };
  return (
    <main className=" grid grid-cols-1 lg:max-w-full m-auto shadow-xl ">
      <div className="invoice__preview bg-white p-2 rounded">
        <ReactToPrint
          trigger={() => (
            <button
              style={{ backgroundColor: currentColor }}
              className="btn bg-blue-500 ml-5 text-white font-bold py-2 px-8 rounded shadow border-2 border-blue-500 hover:bg-transparent hover:text-blue-500 transition-all duration-300"
            >
              Print / Download
            </button>
          )}
          content={() => componentRef.current}
        />
        <div ref={componentRef} className="bg-white">
          <Header
            className="items-center justify-center"
            handlePrint={handlePrint}
            title={loggedInUser.entity_title}
          />

          <ManifestSummary
            count={location.state.tickets.length}
            value={getValue(location.state.tickets)}
          />

          <ItemsSummary data={location.state.tickets} />

          <Table data={location.state.tickets} />
        </div>
      </div>
    </main>
  );
}
